    //
    (function() {
        const theme = localStorage.getItem('theme') || (window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light');
        document.documentElement.setAttribute('data-bs-theme', theme);
    })();
    //



    /*---------------------------------------------------------
    VARIÁVEIS DO BLOGGER THEME DESIGNER (Ponte Universal)
    -----------------------------------------------------------*/
    /*
    <Group description="Fundo e Cores Base" selector="body">
        <Variable name="body.background" description="Fundo Geral" type="background" color="#f8f9fa" default="$(color) none repeat scroll top left" value="$(color) none repeat scroll top left"/>
        <Variable name="main.color" description="Cor Principal (Destaques)" type="color" default="#0dcaf0" value="#0dcaf0"/>
        <Variable name="theme.text" description="Cor do Texto Principal" type="color" default="#334155" value="#334155"/>
        <Variable name="header.bg" description="Fundo do Cabeçalho" type="color" default="#ffffff" value="#ffffff"/>
        <Variable name="footer.bg" description="Fundo do Rodapé" type="color" default="#1e293b" value="#1e293b"/>
    </Group>


    <Group description="Tipografia" selector="body">
        <Variable name="body.font" description="Fonte do Texto" type="font" default="normal normal 16px system-ui, -apple-system, sans-serif" value="normal normal 16px system-ui, -apple-system, sans-serif"/>
    </Group>
    */


    /* ===================================================
       SOFTLOAD MASTER BASE - CORE CSS (MOBILE-FIRST)
       =================================================== */

    :root {
      /* Defaults do Blogger Theme Designer (fallback) */
      --sl-bg-body:   $(body.background);
      --sl-text-main: $(theme.text);
      --sl-primary:   $(main.color);
      --sl-card-bg:   #ffffff;
      --sl-footer-bg: #1e293b;
      --sl-radius-lg: 16px;
      --sl-transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
      /* Button tokens (default) */
      --sl-btn-radius: 8px;
      --sl-btn-shadow: 0 2px 6px rgba(0,0,0,0.15);
      /* Typography tokens (default) */
      --sl-font-family: system-ui, -apple-system, sans-serif;
      --sl-heading-weight: 700;
    }

    /* Tokens escolhidos pelo usuário — sobrescrevem os defaults acima */
    [[DYNAMIC_CSS]]


    body {
      background-color: var(--sl-bg-body, #f8fafc);
      color: var(--sl-text-main);
      /* font-family vem de --sl-font-family injetado no bloco de tokens acima */
      font-family: var(--sl-font-family, system-ui, sans-serif);
      margin: 0;
      padding: 0;
      overflow-x: hidden;
      -webkit-font-smoothing: antialiased;
    }


    img { max-width: 100%; height: auto; display: block; }
    a { color: var(--sl-primary); text-decoration: none; transition: var(--sl-transition); }
    a:hover { filter: brightness(0.8); }


    /* Feed layout gerido pelo Bootstrap row-cols injetado via GRID_CLASS */


    h1, h2, h3, h4, h5, h6 { font-weight: var(--sl-heading-weight); }

    .btn-primary, .btn-outline-primary {
      border-radius: var(--sl-btn-radius);
      box-shadow: var(--sl-btn-shadow);
    }

    .news-card {
      background: var(--sl-card-bg);
      border: 1px solid rgba(0, 0, 0, 0.05);
      border-radius: var(--sl-radius-lg);
      box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);
      transition: var(--sl-transition);
      overflow: hidden;
    }


    @media (min-width: 992px) {
      .news-card:hover { transform: translateY(-5px); box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.1); }
    }


    .news-card p.text-muted {
      display: -webkit-box;
      -webkit-line-clamp: 3;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }


/* ESTRUTURA DE DROPDOWN (MODULAR) */
.sl-nav ul li { position: relative; list-style: none; }


/* Esconde o submenu por padrão */
.sl-nav ul ul {
  position: absolute;
  top: 100%;
  left: 0;
  display: none;
  background: var(--sl-card-bg);
  min-width: 200px;
  box-shadow: 0 10px 15px -3px rgba(0,0,0,0.1);
  z-index: 99;
}


/* Mostra no Hover (Desktop) */
.sl-nav ul li:hover > ul { display: block; }


/* Ajuste Mobile: Aqui entra o seu JS de Start */
@media (max-width: 768px) {
  .sl-nav ul ul { position: static; box-shadow: none; padding-left: 15px; }
}


    /* ===================================================
       WIDGETS: CATEGORIAS (LABELS)
       =================================================== */
    .sl-label-widget ul { padding: 0; margin: 0; list-style: none; display: flex; flex-wrap: wrap; gap: 8px; }

    /* Lista — pílula solid/soft */
    .sl-label-list a {
      display: inline-block;
      padding: 6px 14px;
      background-color: color-mix(in srgb, var(--sl-primary) 10%, transparent);
      color: var(--sl-primary);
      border-radius: 50px;
      font-size: 0.85rem;
      font-weight: 600;
      transition: var(--sl-transition);
      text-decoration: none;
    }
    .sl-label-list a:hover { background-color: var(--sl-primary); color: #fff; filter: none; }

    /* Nuvem — outline com scale no hover */
    .sl-label-cloud a {
      display: inline-block;
      padding: 4px 12px;
      border: 1px solid var(--sl-primary);
      color: var(--sl-text-main);
      border-radius: var(--sl-radius-lg);
      font-size: 0.9rem;
      transition: var(--sl-transition);
      text-decoration: none;
    }
    .sl-label-cloud a:hover { background-color: var(--sl-primary); color: #fff; transform: translateY(-2px); filter: none; }

    /* ===================================================
       TIPOGRAFIA: BLOCKQUOTE PREMIUM
       =================================================== */
    .post-body blockquote {
      margin: 2rem 0;
      padding: 1.5rem 2rem;
      background-color: color-mix(in srgb, var(--sl-primary) 5%, transparent);
      border-left: 5px solid var(--sl-primary);
      border-radius: 0 var(--sl-radius-lg) var(--sl-radius-lg) 0;
      font-style: italic;
      color: var(--sl-text-main);
      position: relative;
    }
    .post-body blockquote p { margin-bottom: 0; font-size: 1.1rem; line-height: 1.6; }


    /* ===================================================
       BOTÕES OUTLINE PRIMARY — herdam var(--sl-primary)
       =================================================== */
    .btn-outline-primary {
      color: var(--sl-primary);
      border-color: var(--sl-primary);
    }
    .btn-outline-primary:hover,
    .btn-outline-primary:focus,
    .btn-outline-primary:active,
    .btn-outline-primary.active {
      background-color: var(--sl-primary);
      border-color: var(--sl-primary);
      color: #fff;
      filter: none;
    }

    /* ===================================================
       PÁGINA DE ARTIGO: SHARE + AUTHOR BOX
       =================================================== */
    .sl-author-box { box-shadow: 0 4px 6px -1px rgba(0,0,0,0.05); }
    .sl-share-buttons a.btn { flex-shrink: 0; }

    /* ===================================================
       ARTIGOS RELACIONADOS
       =================================================== */
    .sl-related-posts .news-card { height: 100%; }
    .sl-related-posts .news-card img {
      width: 100%;
      aspect-ratio: 16 / 9;
      object-fit: cover;
      display: block;
    }


