  //
  document.addEventListener('DOMContentLoaded', function() {
      const SL_Engine = {
          init: function() { console.log('Softload Master Base Initialized'); }
      };
      SL_Engine.init();
  });
  //




  //
  (function () {
    const grid = document.getElementById('sl-related-ready');
    if (!grid) return;

    function esc(s) {
      return String(s)
        .replace(/&/g, '&amp;').replace(/</g, '&lt;')
        .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
    }

    const label      = (document.getElementById('sl-post-label') || {}).textContent.trim();
    const currentUrl = (document.getElementById('sl-post-url')   || {}).textContent.trim();

    if (!label) { grid.closest('.sl-related-posts').style.display = 'none'; return; }

    fetch('/feeds/posts/default/-/' + encodeURIComponent(label) + '?alt=json&max-results=4')
      .then(function (r) { if (!r.ok) throw 0; return r.json(); })
      .then(function (data) {
        const entries = (data.feed.entry || [])
          .filter(function (e) {
            const lnk = (e.link || []).filter(function (l) { return l.rel === 'alternate'; })[0];
            return lnk && lnk.href !== currentUrl;
          })
          .slice(0, 3);

        if (!entries.length) { grid.closest('.sl-related-posts').style.display = 'none'; return; }

        grid.innerHTML = entries.map(function (e) {
          const lnk   = (e.link || []).filter(function (l) { return l.rel === 'alternate'; })[0];
          const url   = esc(lnk ? lnk.href : '#');
          const title = esc((e.title || {}).$t || '');
          const cat   = esc(((e.category || [])[0] || {}).term || '');
          const raw   = (e.media$thumbnail || {}).url || '';
          const thumb = esc(raw
            ? raw.replace(/\/s[\d]+-c(\/|$)/, '/w400-h225-c/')
            : '[[PLACEHOLDER_IMG]]');
          const date  = (e.published || {}).$t
            ? new Date(e.published.$t).toLocaleDateString('pt-BR') : '';

          return '<div class="col">'
            + '<article class="news-card d-flex flex-column h-100">'
            + '<a href="' + url + '">'
            + '<img src="' + thumb + '" alt="' + title + '" class="w-100"'
            + ' style="object-fit:cover;aspect-ratio:16/9;"/>'
            + '</a>'
            + '<div class="p-3 d-flex flex-column flex-grow-1 border-top">'
            + (cat ? '<span class="text-primary fw-bold small mb-2 text-uppercase">' + cat + '</span>' : '')
            + '<h3 class="h6 fw-bold mb-2">'
            + '<a class="text-body text-decoration-none" href="' + url + '">' + title + '</a>'
            + '</h3>'
            + '<div class="mt-auto small text-muted">'
            + '<i class="bi bi-clock me-1"></i>' + esc(date)
            + '</div>'
            + '</div>'
            + '</article>'
            + '</div>';
        }).join('');
      })
      .catch(function () { grid.closest('.sl-related-posts').style.display = 'none'; });
  })();
  //




  [[NICHO_JS]]
